/**
 * Pre-warms and verifies that all essential Vazirmatn font weights
 * are loaded into document.fonts before rendering to canvas.
 */
export async function ensureVazirmatnFontsLoaded(): Promise<void> {
  if (typeof window === 'undefined') return;
  try {
    if (document.fonts) {
      await document.fonts.ready;
      await Promise.allSettled([
        document.fonts.load('400 12px Vazirmatn'),
        document.fonts.load('500 12px Vazirmatn'),
        document.fonts.load('600 12px Vazirmatn'),
        document.fonts.load('700 12px Vazirmatn'),
        document.fonts.load('800 12px Vazirmatn'),
        document.fonts.load('900 12px Vazirmatn'),
      ]);
      await document.fonts.ready;
    }
  } catch (e) {
    console.warn('Font loading check error:', e);
  }
}
